3. /// <summary>
4. /// Configurable data transformation pipeline that processes records through
5. /// a series of stages: validation, transformation, enrichment, and output.
6. /// </summary>
7. public class DataPipeline
8. {
9.     // PERF: unsealed class — JIT cannot devirtualize calls to Record
10.     public class Record
11.     {
12.         public string Id { get; set; } = "";
13.         public Dictionary<string, string> Fields { get; set; } = new();
14.         public List<string> Tags { get; set; } = new();
15.         public DateTime ProcessedAt { get; set; }
16.     }
17. 
18.     public class PipelineResult
19.     {
20.         public List<Record> Processed { get; set; } = new();
21.         public List<(Record Record, string Error)> Failed { get; set; } = new();
22.         public TimeSpan Duration { get; set; }
23.         public Dictionary<string, int> StageMetrics { get; set; } = new();
24.     }
25. 
26.     private readonly List<Func<Record, Record?>> _validators = new();
27.     private readonly List<Func<Record, Record>> _transformers = new();
28.     private readonly List<Func<Record, Record>> _enrichers = new();
29. 
30.     public DataPipeline AddValidator(Func<Record, Record?> validator)
31.     {
32.         _validators.Add(validator);
33.         return this;
34.     }
35. 
