154.                 if (r.Fields.Count == 0) return null;
155.                 return r;
156.             })
157.             .AddTransformer(r =>
158.             {
159.                 // PERF: new Dictionary per record + .ToLower() per field key
160.                 var normalized = new Dictionary<string, string>();
161.                 foreach (var field in r.Fields)
162.                 {
163.                     normalized[field.Key.ToLower()] = field.Value.Trim();
164.                 }
165.                 r.Fields = normalized;
166.                 return r;
167.             })
168.             .AddTransformer(r =>
169.             {
170.                 var cleaned = new Dictionary<string, string>();
171.                 foreach (var field in r.Fields)
172.                 {
173.                     if (!string.IsNullOrWhiteSpace(field.Value))
174.                         cleaned[field.Key] = field.Value;
175.                 }
176.                 r.Fields = cleaned;
177.                 return r;
178.             })
179.             .AddEnricher(r =>
180.             {
181.                 foreach (var field in r.Fields)
182.                 {
183.                     // PERF: .Contains on string called in nested loop
184.                     if (field.Value.Contains("@") && field.Value.Contains("."))
185.                         r.Tags.Add("has-email");
186.                     // PERF: .Any(char.IsDigit) — LINQ overhead on every field value
187.                     if (field.Value.Any(char.IsDigit))
188.                         r.Tags.Add("has-numbers");
189.                 }
190.                 // PERF: .Distinct().ToList() allocates two collections to deduplicate
191.                 r.Tags = r.Tags.Distinct().ToList();
192.                 return r;
193.             });
194.     }
