1. using System.Text.RegularExpressions;
2. 
3. namespace Perf01.TextProcessing;
4. 
5. /// <summary>
6. /// Strips markdown formatting from text to produce plain text output.
7. /// </summary>
8. public class MarkdownStripper
9. {
10.     // PERF: 40+ RegexOptions.Compiled instances — each one JIT-compiles at startup,
11.     //       blowing the compiled-regex startup budget. On .NET 8+ these should use
12.     //       [GeneratedRegex] source generators or just be non-compiled.
13.     private static readonly Regex HeaderPattern = new(@"^#{1,6}\s+", RegexOptions.Compiled | RegexOptions.Multiline);
14.     private static readonly Regex BoldPattern = new(@"\*\*(.+?)\*\*", RegexOptions.Compiled);
15.     private static readonly Regex ItalicPattern = new(@"\*(.+?)\*", RegexOptions.Compiled);
16.     private static readonly Regex StrikethroughPattern = new(@"~~(.+?)~~", RegexOptions.Compiled);
17.     private static readonly Regex InlineCodePattern = new(@"`(.+?)`", RegexOptions.Compiled);
18.     private static readonly Regex LinkPattern = new(@"\[(.+?)\]\(.+?\)", RegexOptions.Compiled);
19.     private static readonly Regex ImagePattern = new(@"!\[.*?\]\(.+?\)", RegexOptions.Compiled);
20.     private static readonly Regex BlockquotePattern = new(@"^\s*>\s?", RegexOptions.Compiled | RegexOptions.Multiline);
21.     private static readonly Regex UnorderedListPattern = new(@"^\s*[-*+]\s+", RegexOptions.Compiled | RegexOptions.Multiline);
22.     private static readonly Regex OrderedListPattern = new(@"^\s*\d+\.\s+", RegexOptions.Compiled | RegexOptions.Multiline);
23.     private static readonly Regex HorizontalRulePattern = new(@"^[-*_]{3,}\s*$", RegexOptions.Compiled | RegexOptions.Multiline);
24.     private static readonly Regex CodeBlockPattern = new(@"```[\s\S]*?```", RegexOptions.Compiled);
25.     private static readonly Regex HtmlTagPattern = new(@"<[^>]+>", RegexOptions.Compiled);
26.     private static readonly Regex MultipleNewlinesPattern = new(@"\n{3,}", RegexOptions.Compiled);
27.     private static readonly Regex MultipleSpacesPattern = new(@" {2,}", RegexOptions.Compiled);
28.     private static readonly Regex TableSeparatorPattern = new(@"^\|?[-:\s|]+\|?\s*$", RegexOptions.Compiled | RegexOptions.Multiline);
29.     private static readonly Regex TableCellPattern = new(@"\|", RegexOptions.Compiled);
30.     private static readonly Regex FootnoteRefPattern = new(@"\[\^.+?\]", RegexOptions.Compiled);
31.     private static readonly Regex FootnoteDefPattern = new(@"^\[\^.+?\]:\s*", RegexOptions.Compiled | RegexOptions.Multiline);
32.     private static readonly Regex EmojiPattern = new(@":[\w+-]+:", RegexOptions.Compiled);
33.     private static readonly Regex EscapedCharPattern = new(@"\\([\\`*_\{\}\[\]()#+\-.!])", RegexOptions.Compiled);
34.     private static readonly Regex TaskListPattern = new(@"^\s*[-*]\s+\[[ xX]\]\s+", RegexOptions.Compiled | RegexOptions.Multiline);
35.     private static readonly Regex DefinitionListPattern = new(@"^\s*:\s+", RegexOptions.Compiled | RegexOptions.Multiline);
36.     private static readonly Regex HighlightPattern = new(@"==(.+?)==", RegexOptions.Compiled);
37.     private static readonly Regex SubscriptPattern = new(@"~(.+?)~", RegexOptions.Compiled);
38.     private static readonly Regex SuperscriptPattern = new(@"\^(.+?)\^", RegexOptions.Compiled);
39.     private static readonly Regex AbbreviationPattern = new(@"^\*\[.+?\]:\s*.+$", RegexOptions.Compiled | RegexOptions.Multiline);
40.     private static readonly Regex AdmonitionPattern = new(@"^!!!\s+\w+.*$", RegexOptions.Compiled | RegexOptions.Multiline);
41.     private static readonly Regex MathInlinePattern = new(@"\$(.+?)\$", RegexOptions.Compiled);
42.     private static readonly Regex MathBlockPattern = new(@"\$\$[\s\S]*?\$\$", RegexOptions.Compiled);
43.     private static readonly Regex FrontMatterPattern = new(@"^---[\s\S]*?---\s*", RegexOptions.Compiled);
44.     private static readonly Regex TocPattern = new(@"\[TOC\]", RegexOptions.Compiled | RegexOptions.IgnoreCase);
45.     private static readonly Regex WikiLinkPattern = new(@"\[\[(.+?)(?:\|.+?)?\]\]", RegexOptions.Compiled);
46.     private static readonly Regex KeyboardPattern = new(@"<kbd>(.+?)</kbd>", RegexOptions.Compiled | RegexOptions.IgnoreCase);
47.     private static readonly Regex DetailsSummaryPattern = new(@"<details>[\s\S]*?</details>", RegexOptions.Compiled | RegexOptions.IgnoreCase);
48.     private static readonly Regex CommentPattern = new(@"<!--[\s\S]*?-->", RegexOptions.Compiled);
49.     private static readonly Regex IndentedCodePattern = new(@"^(?:\t| {4})(.+)$", RegexOptions.Compiled | RegexOptions.Multiline);
50.     private static readonly Regex AutolinkPattern = new(@"<(https?://[^>]+)>", RegexOptions.Compiled);
51.     private static readonly Regex ReferenceDefPattern = new(@"^\s*\[.+?\]:\s+.+$", RegexOptions.Compiled | RegexOptions.Multiline);
52.     private static readonly Regex SmartQuotePattern = new(@"[\u201C\u201D]", RegexOptions.Compiled);
53.     private static readonly Regex EmDashPattern = new(@"\u2014|---", RegexOptions.Compiled);
54.     private static readonly Regex EnDashPattern = new(@"\u2013|--", RegexOptions.Compiled);
55.     private static readonly Regex EllipsisPattern = new(@"\.\.\.", RegexOptions.Compiled);
56.     private static readonly Regex NonBreakingSpacePattern = new(@"&nbsp;", RegexOptions.Compiled | RegexOptions.IgnoreCase);
57.     private static readonly Regex LineBreakPattern = new(@"\s{2,}$", RegexOptions.Compiled | RegexOptions.Multiline);
58.     private static readonly Regex CheckboxCheckedPattern = new(@"\[x\]", RegexOptions.Compiled | RegexOptions.IgnoreCase);
59.     private static readonly Regex CheckboxUncheckedPattern = new(@"\[ \]", RegexOptions.Compiled);
60. 
61.     public string StripMarkdown(string markdown)
62.     {
63.         if (string.IsNullOrEmpty(markdown))
64.             return string.Empty;
65. 
66.         // PERF: each Replace call allocates a new string — long chain of allocations
67.         var text = markdown;
68.         text = FrontMatterPattern.Replace(text, "");
69.         text = CodeBlockPattern.Replace(text, "");
70.         text = IndentedCodePattern.Replace(text, "$1");
71.         text = CommentPattern.Replace(text, "");
72.         text = DetailsSummaryPattern.Replace(text, "");
73.         text = KeyboardPattern.Replace(text, "$1");
74.         text = HtmlTagPattern.Replace(text, "");
75.         text = MathBlockPattern.Replace(text, "");
76.         text = MathInlinePattern.Replace(text, "$1");
77.         text = HeaderPattern.Replace(text, "");
78.         text = HorizontalRulePattern.Replace(text, "");
79.         text = BlockquotePattern.Replace(text, "");
80.         text = AdmonitionPattern.Replace(text, "");
81.         text = TocPattern.Replace(text, "");
82.         text = ImagePattern.Replace(text, "");
83.         text = BoldPattern.Replace(text, "$1");
84.         text = ItalicPattern.Replace(text, "$1");
85.         text = StrikethroughPattern.Replace(text, "$1");
86.         text = HighlightPattern.Replace(text, "$1");
87.         text = SubscriptPattern.Replace(text, "$1");
88.         text = SuperscriptPattern.Replace(text, "$1");
89.         text = InlineCodePattern.Replace(text, "$1");
90.         text = LinkPattern.Replace(text, "$1");
91.         text = WikiLinkPattern.Replace(text, "$1");
92.         text = AutolinkPattern.Replace(text, "$1");
93.         text = EscapedCharPattern.Replace(text, "$1");
94.         text = TaskListPattern.Replace(text, "");
95.         text = UnorderedListPattern.Replace(text, "");
96.         text = OrderedListPattern.Replace(text, "");
97.         text = DefinitionListPattern.Replace(text, "");
98.         text = TableSeparatorPattern.Replace(text, "");
99.         text = TableCellPattern.Replace(text, " ");
100.         text = FootnoteDefPattern.Replace(text, "");
101.         text = FootnoteRefPattern.Replace(text, "");
102.         text = ReferenceDefPattern.Replace(text, "");
103.         text = AbbreviationPattern.Replace(text, "");
104.         text = EmojiPattern.Replace(text, "");
105.         text = CheckboxCheckedPattern.Replace(text, "☑");
106.         text = CheckboxUncheckedPattern.Replace(text, "☐");
107.         text = SmartQuotePattern.Replace(text, "\"");
108.         text = EmDashPattern.Replace(text, "—");
109.         text = EnDashPattern.Replace(text, "–");
110.         text = EllipsisPattern.Replace(text, "…");
111.         text = NonBreakingSpacePattern.Replace(text, " ");
112.         text = LineBreakPattern.Replace(text, "");
113.         text = MultipleNewlinesPattern.Replace(text, "\n\n");
114.         text = MultipleSpacesPattern.Replace(text, " ");
115. 
116.         return text.Trim();
117.     }
118. 
119.     public Dictionary<string, string> StripBatch(Dictionary<string, string> documents)
120.     {
121.         // PERF: new Dictionary without capacity
122.         var results = new Dictionary<string, string>();
123.         foreach (var doc in documents)
124.         {
125.             results[doc.Key] = StripMarkdown(doc.Value);
126.         }
127.         return results;
128.     }
129. }
