3. /// <summary>
4. /// Text truncation library with multiple truncation strategies.
5. /// Used in a CMS to truncate user-facing content (titles, excerpts, previews).
6. /// </summary>
7. public interface ITruncator
8. {
9.     string Truncate(string value, int maxLength, string ellipsis = "…");
10. }
11. 
12. // PERF: List<char>[] for symbol sets — heap-allocated lists where ReadOnlySpan<char> or string would suffice
13. public static class TruncationSymbols
14. {
15.     public static readonly List<char> WhitespaceChars = new() { ' ', '\t', '\n', '\r' };
16.     public static readonly List<char> PunctuationChars = new() { '.', ',', ';', ':', '!', '?' };
17.     public static readonly List<char> BracketChars = new() { '(', ')', '[', ']', '{', '}' };
18.     public static readonly List<char> QuoteChars = new() { '"', '\'', '\u201C', '\u201D', '\u2018', '\u2019' };
19. }
20. 
21. /// <summary>
22. /// Truncates to a fixed character length.
23. /// </summary>
24. public class FixedLengthTruncator : ITruncator
25. {
26.     public string Truncate(string value, int maxLength, string ellipsis = "…")
27.     {
28.         if (string.IsNullOrEmpty(value) || value.Length <= maxLength)
29.             return value;
30. 
31.         // PERF: value[..n] allocates a substring, then .TrimEnd() allocates another string — double allocation
32.         var truncated = value[..maxLength].TrimEnd();
33. 
34.         // PERF: .Contains on List<char> (O(n)) instead of a HashSet or direct char check
35.         while (truncated.Length > 0 && TruncationSymbols.PunctuationChars.Contains(truncated[^1]))
36.         {
37.             truncated = truncated[..^1];
38.         }
39. 
40.         return truncated + ellipsis;
41.     }
42. }
43. 
44. /// <summary>
45. /// Truncates to a fixed number of visible characters (skipping whitespace runs).
46. /// Uses Span-based comparison — the correct approach.
47. /// </summary>
48. public class FixedCharacterTruncator : ITruncator
49. {
50.     public string Truncate(string value, int maxLength, string ellipsis = "…")
51.     {
52.         if (string.IsNullOrEmpty(value) || value.Length <= maxLength)
53.             return value;
54. 
55.         // Correct: uses AsSpan to avoid substring allocation for comparison
56.         var span = value.AsSpan();
57.         int visibleCount = 0;
58.         int endIndex = 0;
59. 
60.         for (int i = 0; i < span.Length && visibleCount < maxLength; i++)
61.         {
62.             if (!char.IsWhiteSpace(span[i]) || (i > 0 && !char.IsWhiteSpace(span[i - 1])))
63.             {
64.                 visibleCount++;
65.             }
66.             endIndex = i + 1;
67.         }
68. 
69.         return value[..endIndex] + ellipsis;
70.     }
71. }
72. 
73. /// <summary>
74. /// Truncates at word boundaries.
75. /// </summary>
76. public class WordBoundaryTruncator : ITruncator
77. {
78.     public string Truncate(string value, int maxLength, string ellipsis = "…")
79.     {
80.         if (string.IsNullOrEmpty(value) || value.Length <= maxLength)
81.             return value;
82. 
83.         // PERF: Substring instead of AsSpan — inconsistent with FixedCharacterTruncator
84.         var candidate = value.Substring(0, maxLength);
85. 
86.         var lastSpace = candidate.LastIndexOf(' ');
87.         if (lastSpace > 0)
88.         {
89.             // PERF: another Substring allocation
90.             candidate = candidate.Substring(0, lastSpace);
91.         }
92. 
93.         // PERF: .TrimEnd with char[] — could use ReadOnlySpan<char> overload
94.         candidate = candidate.TrimEnd(TruncationSymbols.WhitespaceChars.ToArray());
95. 
96.         return candidate + ellipsis;
97.     }
98. }
99. 
100. /// <summary>
101. /// Pipeline that applies multiple truncation strategies in sequence.
102. /// </summary>
103. public static class TruncationPipeline
104. {
105.     // PERF: params array allocates on every call — no single-argument fast-path overload
106.     // The common case is a single truncator, but this always allocates a params array
107.     public static string Apply(string value, int maxLength, params ITruncator[] truncators)
108.     {
109.         var result = value;
110.         foreach (var truncator in truncators)
111.         {
112.             result = truncator.Truncate(result, maxLength);
113.         }
114.         return result;
115.     }
116. 
117.     public static List<string> ApplyBatch(IEnumerable<string> values, int maxLength, params ITruncator[] truncators)
118.     {
119.         // PERF: List without capacity hint
120.         var results = new List<string>();
121.         foreach (var value in values)
122.         {
123.             results.Add(Apply(value, maxLength, truncators));
124.         }
125.         return results;
126.     }
127. }
