3. /// <summary>
4. /// Formats numbers with SI/metric unit prefixes (k, M, G, T, etc.).
5. /// Used in a monitoring dashboard rendering thousands of data points per second.
6. /// </summary>
7. public class MetricFormatter
8. {
9.     public struct UnitPrefix
10.     {
11.         public string Symbol { get; set; }
12.         public string Name { get; set; }
13.         public double Factor { get; set; }
14. 
15.         // PERF: struct lacks IEquatable<UnitPrefix> — boxing on equality checks in collections
16.     }
17. 
18.     // All SI prefixes from yocto to yotta
19.     private static readonly List<UnitPrefix> Prefixes = new()
20.     {
21.         new() { Symbol = "Y", Name = "yotta", Factor = 1e24 },
22.         new() { Symbol = "Z", Name = "zetta", Factor = 1e21 },
23.         new() { Symbol = "E", Name = "exa",   Factor = 1e18 },
24.         new() { Symbol = "P", Name = "peta",  Factor = 1e15 },
25.         new() { Symbol = "T", Name = "tera",  Factor = 1e12 },
26.         new() { Symbol = "G", Name = "giga",  Factor = 1e9 },
27.         new() { Symbol = "M", Name = "mega",  Factor = 1e6 },
28.         new() { Symbol = "k", Name = "kilo",  Factor = 1e3 },
29.         new() { Symbol = "h", Name = "hecto", Factor = 1e2 },
30.         new() { Symbol = "da", Name = "deca", Factor = 1e1 },
31.         new() { Symbol = "d", Name = "deci",  Factor = 1e-1 },
32.         new() { Symbol = "c", Name = "centi", Factor = 1e-2 },
33.         new() { Symbol = "m", Name = "milli", Factor = 1e-3 },
34.         new() { Symbol = "μ", Name = "micro", Factor = 1e-6 },
35.         new() { Symbol = "n", Name = "nano",  Factor = 1e-9 },
36.         new() { Symbol = "p", Name = "pico",  Factor = 1e-12 },
37.     };
38. 
39.     public string FormatWithPrefix(double value, string unit)
40.     {
41.         foreach (var prefix in Prefixes)
42.         {
43.             if (Math.Abs(value) >= prefix.Factor)
44.             {
45.                 var scaled = value / prefix.Factor;
46.                 return $"{scaled:F2} {prefix.Symbol}{unit}";
47.             }
48.         }
49.         return $"{value:F2} {unit}";
50.     }
51. 
52.     /// <summary>
53.     /// Expands abbreviated unit prefix symbols in a display string to full names.
54.     /// E.g., "5.2 kB" → "5.2 kiloB"
55.     /// </summary>
56.     public string ExpandPrefixSymbols(string displayValue)
57.     {
58.         // PERF: .Aggregate() calling .Replace() over 16 prefixes — creates 16 intermediate string allocations
59.         // Each .Replace() scans the entire string and allocates a new copy even if no match is found
60.         return Prefixes.Aggregate(displayValue, (current, prefix) =>
61.         {
62.             // PERF: char.ToString() allocation per prefix lookup iteration
63.             // (for single-char symbols, this allocates a new string each time)
64.             var symbol = prefix.Symbol.Length == 1 ? prefix.Symbol[0].ToString() : prefix.Symbol;
65.             return current.Replace(symbol, prefix.Name);
66.         });
67.     }
68. 
69.     /// <summary>
70.     /// Formats a batch of values with the best-fit prefix.
71.     /// </summary>
72.     public List<string> FormatBatch(IEnumerable<(double Value, string Unit)> items)
73.     {
74.         // PERF: List without capacity hint
75.         var results = new List<string>();
76.         foreach (var (value, unit) in items)
77.         {
78.             results.Add(FormatWithPrefix(value, unit));
79.         }
80.         return results;
81.     }
82. }
