85. // Ordinalizer hierarchy — converts numbers to ordinal strings (1st, 2nd, etc.)
86. // for different locales.
87. // ---------------------------------------------------------------------------
88. 
89. /// <summary>
90. /// Base class for converting numbers to ordinal representation.
91. /// Abstract — should NOT be sealed.
92. /// </summary>
93. public abstract class Ordinalizer
94. {
95.     public abstract string Convert(int number);
96.     public abstract string Convert(int number, GrammaticalGender gender);
97. 
98.     public string ConvertBatch(IEnumerable<int> numbers)
99.     {
100.         // PERF: string concatenation in loop
101.         var result = "";
102.         foreach (var n in numbers)
103.         {
104.             result += Convert(n) + ", ";
105.         }
106.         return result.TrimEnd(',', ' ');
107.     }
108. }
109. 
110. public enum GrammaticalGender
111. {
112.     Masculine,
113.     Feminine,
114.     Neuter
115. }
116. 
117. /// <summary>
118. /// Default ordinalizer with English-like suffix rules.
119. /// This is a BASE class — EnglishOrdinalizer and GermanOrdinalizer extend it.
120. /// Should NOT be sealed.
121. /// </summary>
122. // PERF: unsealed class (correct — this is a base class with subclasses)
123. public class DefaultOrdinalizer : Ordinalizer
124. {
125.     public override string Convert(int number)
126.     {
127.         return Convert(number, GrammaticalGender.Masculine);
128.     }
129. 
130.     public override string Convert(int number, GrammaticalGender gender)
131.     {
132.         var suffix = GetSuffix(number);
133.         return number.ToString() + suffix;
134.     }
135. 
136.     protected virtual string GetSuffix(int number)
137.     {
138.         var abs = Math.Abs(number);
139.         var lastTwoDigits = abs % 100;
140.         var lastDigit = abs % 10;
141. 
142.         if (lastTwoDigits >= 11 && lastTwoDigits <= 13)
143.             return "th";
144. 
145.         return lastDigit switch
146.         {
147.             1 => "st",
148.             2 => "nd",
149.             3 => "rd",
150.             _ => "th"
151.         };
152.     }
153. }
154. 
155. /// <summary>
156. /// English ordinalizer. Leaf class — should be sealed for JIT devirtualization.
157. /// </summary>
158. // PERF: unsealed leaf class — should be sealed for JIT devirtualization
159. public class EnglishOrdinalizer : DefaultOrdinalizer
160. {
161.     // English uses the same rules as Default — this subclass exists for
162.     // locale registration and potential future customization
163.     protected override string GetSuffix(int number)
164.     {
165.         return base.GetSuffix(number);
166.     }
167. }
