private static readonly Regex AccentedERegex = new(@"[èéêë]", RegexOptions.Compiled);
// ... etc for other patterns

// Use culture-aware ToLower and StringBuilder for replacements
var slug = input.ToLowerInvariant();
var sb = new StringBuilder(slug);
foreach (var kvp in ReplacementMap)
{
