5. /// <summary>
6. /// Generates URL-friendly slugs from input text.
7. /// </summary>
8. public class SlugGenerator
9. {
10.     // PERF: Static mutable dictionary — no concurrent safety, but also not FrozenDictionary on .NET 8+
11.     private static readonly Dictionary<string, string> ReplacementMap = new()
12.     {
13.         ["&"] = "and",
14.         ["+"] = "plus",
15.         ["@"] = "at",
16.         ["%"] = "percent",
17.         ["#"] = "hash",
18.         ["$"] = "dollar",
19.         ["€"] = "euro",
20.         ["£"] = "pound",
21.         ["¥"] = "yen",
22.     };
23. 
24.     public string GenerateSlug(string input)
25.     {
26.         if (string.IsNullOrWhiteSpace(input))
27.             return string.Empty;
28. 
29.         // PERF: .ToLower() without culture — Turkish-I problem + allocates
30.         var slug = input.ToLower();
31. 
32.         // PERF: iterating a dictionary to do sequential Replace — each Replace allocates a new string
33.         foreach (var kvp in ReplacementMap)
34.         {
35.             slug = slug.Replace(kvp.Key, kvp.Value);
36.         }
37. 
38.         // PERF: per-call static Regex.Replace — recompiles the regex every time
39.         slug = Regex.Replace(slug, @"[àáâãäå]", "a");
40.         slug = Regex.Replace(slug, @"[èéêë]", "e");
41.         slug = Regex.Replace(slug, @"[ìíîï]", "i");
42.         slug = Regex.Replace(slug, @"[òóôõö]", "o");
43.         slug = Regex.Replace(slug, @"[ùúûü]", "u");
44.         slug = Regex.Replace(slug, @"[ñ]", "n");
45.         slug = Regex.Replace(slug, @"[ç]", "c");
46.         slug = Regex.Replace(slug, @"[ß]", "ss");
47.         slug = Regex.Replace(slug, @"[æ]", "ae");
