88.         for (int i = 1; i < parts.Length; i++)
89.         {
90.             if (current is Dictionary<string, object> dict)
91.             {
92.                 if (!dict.TryGetValue(parts[i], out var next))
93.                     return null;
94.                 current = next;
95.             }
96.             else
97.             {
98.                 // PERF: reflection on every property access in hot path
99.                 var prop = current?.GetType().GetProperty(parts[i]);
