175.             var avg = entriesWithDuration.Average(e => e.Duration);
176.             // PERF: iterates the list twice (once for avg, once for stddev), then a third time for spikes
177.             var stdDev = Math.Sqrt(entriesWithDuration.Average(e => Math.Pow(e.Duration - avg, 2)));
