         var pattern = new Regex(@"\{\{#if\s+(\w+)\}\}([\s\S]*?)\{\{/if\}\}");
         return pattern.Replace(template, match =>
         {
             var key = match.Groups[1].Value;
             if (context.TryGetValue(key, out var value) && IsTruthy(value))
