121.     {
122.         // PERF: flattens entire doc just to pick specific fields
123.         var source = Flatten(json);
124.         var result = new Dictionary<string, object?>();
125. 
126.         foreach (var mapping in fieldMapping)
127.         {
128.             var sourceKey = mapping.Value;
129.             var targetKey = mapping.Key;
130. 
131.             if (source.ContainsKey(sourceKey))
132.                 result[targetKey] = source[sourceKey];
133.         }
134. 
135.         return JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true });
136.     }
137. 
138.     public string PrettyPrint(string json)
139.     {
140.         var element = JsonSerializer.Deserialize<JsonElement>(json);
141.         // PERF: new JsonSerializerOptions on every call
142.         return JsonSerializer.Serialize(element, new JsonSerializerOptions { WriteIndented = true });
143.     }
144. 
145.     public List<Dictionary<string, object?>> FlattenArray(string jsonArray)
146.     {
147.         var array = JsonSerializer.Deserialize<JsonElement>(jsonArray);
148.         var results = new List<Dictionary<string, object?>>();
149. 
150.         if (array.ValueKind == JsonValueKind.Array)
151.         {
152.             foreach (var item in array.EnumerateArray())
153.             {
154.                 var flat = new Dictionary<string, object?>();
155.                 FlattenElement(item, "", flat);
156.                 results.Add(flat);
157.             }
158.         }
159. 
160.         return results;
161.     }
