3. namespace Perf01.TextProcessing;
4. 
5. /// <summary>
6. /// Simple template engine that replaces placeholders with values.
7. /// Supports {{variable}}, {{#if condition}}...{{/if}}, and {{#each list}}...{{/each}}.
8. /// </summary>
9. public class TemplateEngine
10. {
11.     public string Render(string template, Dictionary<string, object> context)
12.     {
13.         if (string.IsNullOrEmpty(template))
14.             return string.Empty;
15. 
16.         var result = template;
17.         result = ProcessConditionals(result, context);
18.         result = ProcessLoops(result, context);
19.         result = ReplaceVariables(result, context);
20. 
21.         // PERF: per-call Regex — compiled on every invocation
22.         result = Regex.Replace(result, @"\{\{.+?\}\}", "");
23. 
24.         return result;
25.     }
26. 
27.     private string ProcessConditionals(string template, Dictionary<string, object> context)
28.     {
29.         // PERF: new Regex allocated every time this method is called
30.         var pattern = new Regex(@"\{\{#if\s+(\w+)\}\}([\s\S]*?)\{\{/if\}\}");
31.         return pattern.Replace(template, match =>
32.         {
33.             var key = match.Groups[1].Value;
34.             if (context.TryGetValue(key, out var value) && IsTruthy(value))
35.                 return match.Groups[2].Value;
36.             return string.Empty;
37.         });
38.     }
39. 
40.     private string ProcessLoops(string template, Dictionary<string, object> context)
41.     {
42.         // PERF: new Regex allocated every call
43.         var pattern = new Regex(@"\{\{#each\s+(\w+)\}\}([\s\S]*?)\{\{/each\}\}");
44.         return pattern.Replace(template, match =>
45.         {
46.             var key = match.Groups[1].Value;
47.             var body = match.Groups[2].Value;
48. 
49.             if (!context.TryGetValue(key, out var value) || value is not IEnumerable<object> items)
50.                 return string.Empty;
51. 
52.             // PERF: string concatenation in a loop — O(n²) allocation pattern
53.             var output = "";
54.             var index = 0;
55.             foreach (var item in items)
56.             {
57.                 // PERF: new Dictionary per iteration, copying entire context
58.                 var iterContext = new Dictionary<string, object>(context)
59.                 {
60.                     ["item"] = item,
61.                     ["index"] = index
62.                 };
63.                 output += ReplaceVariables(body, iterContext);
64.                 index++;
65.             }
66.             return output;
67.         });
68.     }
69. 
70.     private string ReplaceVariables(string template, Dictionary<string, object> context)
71.     {
72.         // PERF: per-call Regex.Replace with a new pattern
73.         return Regex.Replace(template, @"\{\{(\w+(?:\.\w+)*)\}\}", match =>
74.         {
