         foreach (var line in lines)
         {
             if (string.IsNullOrWhiteSpace(line)) continue;
             var entry = TryParseLine(line);
             if (entry != null)
                 entries.Add(entry);
         }

         return entries;
     }

     private LogEntry? TryParseLine(string line)
     {
